4년 시정 성과 전면 부각… 대규모 선대위 공식 출범 권기창 안동시장이 11일 선거사무소 개소식에서 지지자들에게 인사말을 하고 있다. 권기창 안동시장이 11일 선거사무소 개소식에서 딸이 전달한 ‘필승의 빨간 운동화’의 끈을 묶으며 재선 의지를 다지고 있다. 국민의힘 안동시장 예비후보인 권기창 시장이 지난 11일 선거사무소 개소식을 열고 재선 도전을 위한 본격적인 세 결집에 나섰다. 이날 행사장 일대에는 지지자와 당원 3000여 명이 몰렸고, 선거사무소 주변에는 화환과 화분 1000여 개가 늘어서며 거리를 가득 메웠다. 권 시장은 이날 개소식에서 지난 4년간의 시정 성과를 전면에 내세우며 재선 당위성을 강조했다. 특히 전국 기초단체장 공약이행 평가에서 안동시 최초로 4년 연속 최우수(SA) 등급을 받은 점을 주요 성과로 부각했다. (function(d,a,b,l,e,r) {if(d[b]&&d[b].q)return;d[b]=function(){(d[b].q=d[b].q||[]).push(arguments)};e=a.createElement(l);e.async=1;e.charset='utf-8';e.src='//static.dable.io/dist/plugin.min.js';r=a.getElementsByTagName(l)[0];r.parentNode.insertBefore(e,r);})(window,document,'dable','script');dable('setService', 'kbmaeil.com');dable('renderWidget', 'dablewidget_zlvm4x17', {ignore_items: true}); 권 시장은 인사말에서 “4년 전 시민과 함께 새로운 안동을 만들겠다고 약속했고, 새벽부터 밤늦게까지 현장을 누비며 시민 곁을 지켜왔다”며 “그 결과 국가산업단지 조성과 국립의과대학 유치 추진, 자연환경보전지역 해제, 3대 특구 달성 등 민선 8기 성과를 이뤄냈다”고 말했다. 이어 “이 모든 성과는 시민의 믿음과 지지가 있었기에 가능했다”며 “지난 4년의 변화를 완성의 단계로 이어가기 위해 다시 시민 곁에서 뛰겠다”고 밝혔다. 이날 개소식에는 국회 일정으로 참석하지 못한 김형동 국회의원이 축하 메시지를 통해 “안동의 더 큰 도약과 미래 비전을 향한 열정과 헌신이 지역사회에 새로운 활력을 더하는 의미 있는 출발점이 되길 바란다”고 전했다. 이어 국민의힘 권영진·송석준 국회의원을 비롯해 양향자 국민의힘 최고위원, 안상수 전 인천시장, 원유철 전 국회의원 등도 영상으로 축하 인사를 보내 힘을 보탰다. 행사에서는 권 시장의 딸이 무대에 올라 ‘필승의 빨간 운동화’를 직접 건네는 장면이 연출돼 눈길을 끌었다. 권 시장은 무대에서 운동화 끈을 직접 묶은 뒤 “새로운 안동의 완성을 위해 끝까지 전진하겠다”고 밝혔다. 한편 권기창 선거대책위원회는 장대진 전 경북도의회 의장, 김백현 전 안동시의회 의장, 권중덕 안동권씨종친회 원로회 부회장, 권오중 전 안동교육장 등 4인을 공동 상임선대위원장으로 하는 550여 명 규모의 선대위 구성을 마치고 본격적인 선거전에 돌입했다. 글·사진/이도훈기자 ldh@kbmaeil.com (adsbygoogle = window.adsbygoogle || []).push({}); /*<![CDATA[*/ var news = {"id":"20260412500290","title":"\u201C\uC624\uC9C1 \uC548\uB3D9, \uC624\uB85C\uC9C0 \uC2DC\uBBFC\u201D\u2026 \uAD8C\uAE30\uCC3D \uC7AC\uC120 \uD589\uBCF4 \uBCF8\uACA9\uD654","subTitle":"\uC120\uAC70\uC0AC\uBB34\uC18C \uAC1C\uC18C\uC2DD\uC5D0 3000\uC5EC \uBA85 \uC6B4\uC9D1\u2026 \uC138 \uACB0\uC9D1 \uACFC\uC2DC\n4\uB144 \uC2DC\uC815 \uC131\uACFC \uC804\uBA74 \uBD80\uAC01\u20